from pathlib import Path
import base64,zipfile,hashlib,html
R=Path('/home/user/chantier-corrections-bassin-55')
def im(name):return 'data:image/png;base64,'+base64.b64encode((R/name).read_bytes()).decode()
blocks=[('Souche — trait horizontal et retour','avant-apres-souche.png','Le sol est repris, la souche et les poteaux sont conservés.'),('Fleurs — trait vertical','avant-apres-fleurs.png','Seul le sol est modifié ; les fleurs et les poteaux restent en place.'),('Falaise gauche haute','gauche-haut.png','Reprise 53–54 conservée.'),('Falaise gauche milieu','gauche-2.png','Reprise 53–54 conservée : raccord à vérifier visuellement en contexte.'),('Falaise gauche basse','gauche-3.png','Reprise 53–54 conservée.'),('Rebord à droite','droite-falaise.png','Reprise 53–54 conservée.'),('Entre les arbres au sud-ouest','bas-arbres.png','Non corrigé : motif d’ombre présent dans une copie identique de la source ; défaut exact à préciser.')]
sections=''.join(f'<section><h2>{html.escape(a)}</h2><p>{html.escape(c)}</p><img src="{im(b)}" alt="{html.escape(a)}" loading="lazy"></section>' for a,b,c in blocks)
page='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Réverie — capture 55</title><style>body{margin:0;background:#f5f3e9;color:#1c3025;font:16px/1.5 system-ui}header{background:#1b3c2d;color:#fff;padding:26px max(5vw,20px)}main{max-width:1100px;margin:auto;padding:10px 20px 40px}section{background:#fff;border:1px solid #d8ded1;border-radius:12px;padding:18px;margin:18px 0}img{image-rendering:pixelated;max-width:100%;height:auto}h1{margin:.1em 0}h2{font-size:1.2em;margin:.2em 0}.note{background:#fff5d9;padding:14px;border-radius:10px}</style><header><h1>Bassin de Réverie · capture 55</h1><p>Comparaisons locales, non publiées</p></header><main><p class="note">Candidat 53–54 conservé ; deux traits de sol repris. Le cercle entre les arbres du bas reste à examiner. Rendus statiques : pas de validation dans le moteur PMDO.</p>'''+sections+'''<p>Les images des falaises comparent la version initiale et le candidat 53–54. Les images souche et fleurs comparent ce candidat et le nouveau candidat 55.</p></main></html>'''
(R/'apercu-corrections-55.html').write_text(page)
files=['ETAT-CORRECTIONS-55.md','RAPPORT-PREALABLE.md','journal-55.json','apercu-corrections-55.html','candidat/payload/reverie_etang.rsground.gz','candidat/payload/reverie_etang_Dev.rsground.gz','banques/Reverie_Correction_Herbe_55.tile','banques/Reverie_Correction_Ombres_5354.tile','sauvegardes/original-jeu.rsground.gz','sauvegardes/original-dev.rsground.gz','sauvegardes/reverie_etang.rsground.gz','sauvegardes/reverie_etang_Dev.rsground.gz','sauvegardes/journal-53-54.json','sauvegardes/ETAT-CORRECTIONS-53-54.md']
z=R/'candidat-corrections-bassin-55.zip'
with zipfile.ZipFile(z,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=8) as f:
 for p in files:f.write(R/p,p)
with zipfile.ZipFile(z) as f:assert f.testzip() is None
print('Archive CRC OK',len(files),'fichiers',z.stat().st_size,'SHA256',hashlib.sha256(z.read_bytes()).hexdigest())
